<?php
require '../_guard.php';
$errors = []; $values = ['icon' => 'fa-solid fa-star', 'name' => '', 'description' => '', 'active' => '1'];
if ($_SERVER['REQUEST_METHOD'] === 'POST') { foreach (['icon', 'name', 'description'] as $field) $values[$field] = trim($_POST[$field] ?? ''); $values['active'] = isset($_POST['active']) ? '1' : '0'; foreach (['icon', 'name', 'description'] as $field) if ($values[$field] === '') $errors[] = ucfirst($field) . ' is required.'; if (!$errors) { $statement = db()->prepare('INSERT INTO amenities (icon, name, description, active) VALUES (?, ?, ?, ?)'); $statement->execute([$values['icon'], $values['name'], $values['description'], $values['active']]); adminRedirect('amenities', 'message=' . urlencode('Amenity added successfully.')); } }
$pageTitle = 'Add amenity | LFT Admin';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= e($pageTitle) ?></title><link rel="stylesheet" href="../../assets/css/style.css"></head><body><main class="admin-app"><?php require "../sidebar.php"; ?><div class="admin-main"><header class="admin-topbar"><div><p class="section-label">AMENITY CATALOG</p><h1>Add an amenity</h1><p>Create a new public amenity.</p></div><a class="text-link" href="index.php">Back to amenities</a><?php require "../profile.php"; ?></header><section class="admin-widget booking-detail"><?php foreach ($errors as $error): ?><div class="form-error"><?= e($error) ?></div><?php endforeach; ?><form class="admin-editor" method="post"><label>Icon class<input name="icon" value="<?= e($values['icon']) ?>" placeholder="fa-solid fa-wifi" required></label><label>Name<input name="name" value="<?= e($values['name']) ?>" required></label><label>Description<textarea name="description" rows="4" required><?= e($values['description']) ?></textarea></label><label class="admin-checkbox"><input type="checkbox" name="active" <?= $values['active'] === '1' ? 'checked' : '' ?>> Publish this amenity</label><button class="btn btn-green" type="submit">ADD AMENITY</button></form></section></div></main></body></html>
